const tabId = 480038487;
const products = await browserjs(tabId, () => {
  // Let's find product cards on Walgreens productlist page
  const productCards = Array.from(document.querySelectorAll('[class*="product-container"], [data-element-name="product-card"], .card__product, li[class*="product"]'));

  // Also find all links to product pages /store/c/.../ID=...
