args.code:
const tabId = 480038487;
// Let's check the other 3 URLs and see what price / availability they show
const urls = [
  "https://www.walgreens.com/store/c/pokemon-trading-card-game/ID=300443630-product",
  "https://www.walgreens.com/store/c/pokemon-trading-card-game,-elite-trainer-box/ID=300455939-product",
  "https://www.walgreens.com/store/c/pokemon-trading-cards-lightning-set/ID=300425671-product"
];

for (const u of urls) {
  await tool.navigate({ tabId, url: u });
  await tool.wait_for({ tabId, condition: "load_state", value: "load", timeout_ms: 10000 });
  const info = await browserjs(tabId, () => {
    const title = document.querySelector('h1')?.innerText?.trim();
    const priceText = document.querySelector('[data-element-name="product-price"], .product__price, [class*="price"]')?.innerText?.trim();
    const body = document.body?.innerText?.slice(0, 1500);
    // find any dollar amount
    const dollarMatch = body.match(/\$\d+(\.\d{2})?/g);
    const pricedPerStore = body.includes("Priced Per Store") || body.includes("Price available in store");
    return { title, priceText, dollarMatch, pricedPerStore };
  });
  console.log(u, info);
}

